html:
{%- set pmo = pmo_project_status(doc.name) -%}
{#- fecha ISO directa (sin format_date): evita el bug get_locale_value en sesiones sin idioma (PDF/jobs) -#}
{%- macro d(x) -%}{% if x %}{{ x }}{% else %}—{% endif %}{%- endmacro -%}
{%- macro slip(x) -%}{% if x is none %}—{% else %}{{ x }} d{% endif %}{%- endmacro -%}
{%- set health_color = {'En plan':'#1f9d55','En riesgo':'#d97706','Desviado':'#c02b2b'} -%}
<div class="pmo-ps">
<style>
.pmo-ps{font-family:'Helvetica Neue',Arial,sans-serif;color:#222;font-size:12px}
.pmo-ps h1{font-size:20px;margin:0 0 2px}
.pmo-ps .muted{color:#666}
.pmo-ps .band{border-top:3px solid #2b3a67;padding-top:8px;margin-bottom:12px;display:flex;justify-content:space-between;align-items:flex-start}
.pmo-ps .health{font-weight:bold;padding:3px 10px;border-radius:12px;color:#fff;font-size:12px}
.pmo-ps .cards{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}
.pmo-ps .card{border:1px solid #e2e2e2;border-radius:6px;padding:8px 10px;min-width:150px;flex:1}
.pmo-ps .card .lbl{color:#666;font-size:10px;text-transform:uppercase;letter-spacing:.03em}
.pmo-ps .card .val{font-size:15px;font-weight:bold;margin-top:2px}
.pmo-ps .bad{color:#c02b2b}.pmo-ps .ok{color:#1f9d55}
.pmo-ps .bar{background:#eee;border-radius:5px;height:10px;overflow:hidden;margin-top:4px}
.pmo-ps .bar > span{display:block;height:100%;background:#2b3a67}
.pmo-ps h2{font-size:13px;border-bottom:1px solid #ddd;padding-bottom:3px;margin:16px 0 6px}
.pmo-ps table{width:100%;border-collapse:collapse;font-size:11px}
.pmo-ps th,.pmo-ps td{border-bottom:1px solid #eee;padding:5px 6px;text-align:left}
.pmo-ps th{background:#f4f5f8;color:#333}
.pmo-ps td.num{text-align:right}
.pmo-ps .counts{margin:6px 0;color:#444}
.pmo-ps .note{color:#666;font-style:italic;margin-top:6px;font-size:10px}
</style>

<div class="band">
  <div>
    <h1>{{ doc.project_name or doc.name }}</h1>
    <div class="muted">
      {{ doc.get_formatted('status') }}
      {%- if doc.company %} · {{ doc.company }}{% endif %}
      {%- if doc.customer %} · {{ frappe.db.get_value('Customer', doc.customer, 'customer_name') or doc.customer }}{% endif %}
    </div>
    <div class="muted">Fecha de corte (Status Date): <b>{{ d(pmo.status_date) }}</b></div>
  </div>
  <div class="health" style="background:{{ health_color.get(pmo.health, '#666') }}">{{ pmo.health }}</div>
</div>

<h2>Resumen ejecutivo</h2>
<div class="cards">
  <div class="card">
    <div class="lbl">Avance</div>
    <div class="val">{{ (doc.percent_complete or 0) | round(0) | int }}%</div>
    <div class="bar"><span style="width:{{ (doc.percent_complete or 0) | round(0) | int }}%"></span></div>
  </div>
  <div class="card">
    <div class="lbl">Línea base</div>
    <div class="val">{% if pmo.baseline %}{{ d(pmo.baseline.expected_end_date) }}{% else %}— sin baseline{% endif %}</div>
    <div class="muted">Slip vs Baseline: {{ slip(pmo.slip_baseline) }}</div>
  </div>
  <div class="card">
    <div class="lbl">Forecast vigente (plan)</div>
    <div class="val">{{ d(pmo.forecast_end) }}</div>
    <div class="muted">Fin planeado del proyecto (ERPNext)</div>
  </div>
  <div class="card">
    <div class="lbl">Fecha comprometida</div>
    <div class="val">{{ d(pmo.committed_end) }}</div>
    <div class="muted {% if (pmo.slip_committed or 0) > 0 %}bad{% endif %}">Slip vs compromiso: {{ slip(pmo.slip_committed) }}</div>
  </div>
</div>
<div class="cards">
  <div class="card"><div class="lbl">Tareas vencidas al corte</div><div class="val {% if pmo.overdue %}bad{% endif %}">{{ pmo.overdue }}</div></div>
  <div class="card"><div class="lbl">Forecast excede compromiso</div><div class="val {% if pmo.forecast_exceeds %}bad{% endif %}">{{ pmo.forecast_exceeds }}</div></div>
  <div class="card">
    <div class="lbl">Esfuerzo (horas)</div>
    <div class="val">{{ pmo.actual_hours }} / {{ pmo.planned_hours }}</div>
    <div class="muted">% consumido: {% if pmo.pct_consumed is none %}—{% else %}{{ pmo.pct_consumed }}%{% endif %}</div>
  </div>
</div>
<div class="counts">Tareas: <b>{{ pmo.counts.total }}</b> · completadas {{ pmo.counts.completed }} · activas {{ pmo.counts.active }} · vencidas al corte {{ pmo.counts.overdue_at_cutoff }}</div>

{% if pmo.milestones %}
<h2>Hitos</h2>
<table>
  <thead><tr><th>Hito</th><th>Fin (Baseline)</th><th>Fin (Forecast)</th><th class="num">Slip</th><th>Vencido al corte</th></tr></thead>
  <tbody>
  {% for m in pmo.milestones %}
    <tr>
      <td>{{ m.subject }}</td><td>{{ d(m.baseline_exp_end_date) }}</td><td>{{ d(m.current_exp_end_date) }}</td>
      <td class="num">{{ slip(m.slip_days) }}</td><td>{% if m.overdue_at_status_date %}Sí{% else %}—{% endif %}</td>
    </tr>
  {% endfor %}
  </tbody>
</table>
{% endif %}

<h2>Tareas a evaluar (con desviación)</h2>
{% if pmo.relevant_tasks %}
<table>
  <thead><tr><th>Tarea</th><th>Fin (Baseline)</th><th>Fin (Forecast)</th><th class="num">Slip</th><th>Compromiso</th><th>Vencida</th></tr></thead>
  <tbody>
  {% for t in pmo.relevant_tasks %}
    <tr>
      <td>{% if t.is_milestone %}★ {% endif %}{{ t.subject }}</td>
      <td>{{ d(t.baseline_exp_end_date) }}</td>
      <td>{{ d(t.current_exp_end_date) }}</td>
      <td class="num {% if (t.slip_days or 0) > 0 %}bad{% endif %}">{{ slip(t.slip_days) }}</td>
      <td class="{% if t.exceeds_deadline %}bad{% endif %}">{{ d(t.pmo_deadline) }}</td>
      <td>{% if t.overdue_at_status_date %}Sí{% else %}—{% endif %}</td>
    </tr>
  {% endfor %}
  </tbody>
</table>
{% else %}
<div class="muted">Sin tareas con desviación relevante a la fecha de corte.</div>
{% endif %}
{% if pmo.omitted_tasks %}
<div class="note">{{ pmo.omitted_tasks }} tarea(s) con línea base pero sin desviación relevante no se listan (de {{ pmo.total_baseline_tasks }} con baseline).</div>
{% endif %}
</div>
